import re
def parse(p):
    xml=open(p).read()
    out=[]
    for m in re.finditer(r'<row r="(\d+)"[^>]*>(.*?)</row>', xml):
        rn=int(m.group(1)); content=m.group(2)
        for cm in re.finditer(r'<c r="([A-Z]+\d+)"(?: s="(\d+)")?(?: t="([^"]+)")?(/>|>(.*?)</c>)', content):
            ref=cm.group(1); s=cm.group(2); t=cm.group(3); inner=cm.group(5) or ''
            f=re.search(r'<f[^>]*>(.*?)</f>', inner)
            v=re.search(r'<v[^>]*>(.*?)</v>', inner)
            is_=re.search(r'<is><t[^>]*>(.*?)</t></is>', inner)
            if f:
                val='F:'+f.group(1)
            elif v:
                val='V:'+v.group(1)
            elif is_:
                val='S:'+is_.group(1)
            else:
                val=''
            out.append((rn, ref, s, t, val))
    return out
a=parse('/tmp/llm_rollout_ul41ep7h/xlsx_extract/xl/worksheets/sheet1.xml')
b=parse('/tmp/golden_extract/xl/worksheets/sheet1.xml')
